1: import { fileURLToPath } from "node:url";
2: 
3: /**
4:  * Convert an LSP `file://` root URI to a platform filesystem path.
5:  *
6:  * The LSP manager used `rootUri.replace("file://", "")`, which only strips the
7:  * first occurrence and leaves percent-encoding intact, and on Windows turns
8:  * `file:///C:/x` into the invalid `/C:/x`. fileURLToPath does the proper
9:  * platform conversion (drive letters, percent-decoding, UNC).
10:  */
11: export function rootUriToPath(rootUri: string): string {
12:   return fileURLToPath(rootUri);
13: }

1: /**
2:  * LSP Server Manager — manages lifecycle of language server instances.
3:  * Lazy initialization: servers start only when needed.
4:  */
5: 
6: import { LSPClient } from "./client.js";
7: import { BUILTIN_LSP_SERVERS, type LSPServerConfig } from "./servers.js";
8: import { accessSync, constants, statSync } from "node:fs";
9: import { delimiter, extname, join } from "node:path";
10: import { pathToFileURL } from "node:url";
11: import { rootUriToPath } from "./root-path.js";
12: 
13: type ServerState = "stopped" | "starting" | "ready" | "error";
14: 
15: interface ManagedServer {
16:   config: LSPServerConfig;
17:   client: LSPClient | undefined;
18:   state: ServerState;
19:   error?: string;
20: }
21: 
22: export class LSPServerManager {
23:   private servers = new Map<string, ManagedServer>();
24:   private rootUri: string;
25: 
26:   constructor(cwd: string) {
27:     this.rootUri = pathToFileURL(cwd).href;
28: 
29:     // Register all built-in servers
30:     for (const config of BUILTIN_LSP_SERVERS) {
31:       this.servers.set(config.name, { config, client: undefined, state: "stopped" });
32:     }
33:   }
34: 
35:   /**
36:    * Get or start a language server by name.
37:    */
38:   async getClient(serverName: string): Promise<LSPClient | undefined> {
39:     const managed = this.servers.get(serverName);
40:     if (!managed) return undefined;
41: 
42:     if (managed.state === "ready" && managed.client?.isAlive) {
43:       return managed.client;
44:     }
45: 
46:     if (managed.state === "starting") {
47:       // Wait for it to be ready
48:       await new Promise((r) => setTimeout(r, 2000));
49:       return managed.client;
50:     }
51: 
52:     // Try to start
53:     return this.startServer(serverName);
54:   }
55: 
56:   /**
57:    * Start a specific language server.
58:    */
59:   private async startServer(name: string): Promise<LSPClient | undefined> {
60:     const managed = this.servers.get(name);
61:     if (!managed) return undefined;
62: 
63:     // Check if command is available
64:     if (!isCommandAvailable(managed.config.command)) {
65:       managed.state = "error";
66:       managed.error = `${managed.config.command} not found. Install: ${managed.config.installHint}`;
67:       return undefined;
68:     }
69: 
70:     managed.state = "starting";
71: 
72:     try {
73:       const client = new LSPClient(
74:         managed.config.command,
75:         managed.config.args,
76:         rootUriToPath(this.rootUri),
77:       );
78:       await client.start();
79:       await client.initialize(this.rootUri);
80: 
81:       managed.client = client;
82:       managed.state = "ready";
83:       return client;
84:     } catch (err) {
85:       managed.state = "error";
86:       managed.error = (err as Error).message;
87:       return undefined;
88:     }
89:   }
90: 
91:   /**
92:    * Check if any LSP server is connected.
93:    */
94:   isConnected(): boolean {
95:     for (const server of this.servers.values()) {
96:       if (server.state === "ready" && server.client?.isAlive) return true;
97:     }
98:     return false;
99:   }
100: 
101:   /**
102:    * List server statuses.
103:    */
104:   listServers(): Array<{ name: string; language: string; state: ServerState; error?: string }> {
105:     return [...this.servers.values()].map((s) => ({
106:       name: s.config.name,
107:       language: s.config.language,
108:       state: s.state,
109:       error: s.error,
110:     }));
111:   }
112: 
113:   /**
114:    * Shutdown all servers.
115:    */
116:   async shutdownAll(): Promise<void> {
117:     for (const server of this.servers.values()) {
118:       if (server.client?.isAlive) {
119:         try {
120:           await server.client.shutdown();
121:         } catch {
122:           // Force killed
123:         }
124:       }
125:       server.state = "stopped";
126:       server.client = undefined;
127:     }
128:   }
129: }
