131: export function isCommandAvailable(command: string, env: NodeJS.ProcessEnv = process.env): boolean {
132:   const trimmed = command.trim();
133:   if (!trimmed) return false;
134: 
135:   const hasPathSeparator = trimmed.includes("/") || trimmed.includes("\\");
136:   // A bare command with whitespace is not executable via spawn(command, args)
137:   // anyway. Reject it up front so a configured command can never be interpreted
138:   // as shell syntax such as `pylsp; touch /tmp/pwned`.
139:   if (!hasPathSeparator && /\s/.test(trimmed)) return false;
140: 
141:   if (hasPathSeparator) {
142:     return candidateCommandNames(trimmed, env).some(isExecutableFile);
143:   }
144: 
145:   for (const dir of (env.PATH ?? "").split(delimiter)) {
146:     if (!dir) continue;
147:     for (const name of candidateCommandNames(trimmed, env)) {
148:       if (isExecutableFile(join(dir, name))) return true;
149:     }
150:   }
151:   return false;
152: }
153: 
154: function candidateCommandNames(command: string, env: NodeJS.ProcessEnv): string[] {
155:   if (process.platform !== "win32" || extname(command)) return [command];
156:   const pathext = (env.PATHEXT || ".COM;.EXE;.BAT;.CMD")
157:     .split(";")
158:     .map((extension) => extension.trim())
159:     .filter(Boolean);
160:   return [command, ...pathext.map((extension) => `${command}${extension}`)];
161: }
162: 
163: function isExecutableFile(filePath: string): boolean {
164:   try {
165:     const st = statSync(filePath);
166:     if (!st.isFile()) return false;
167:     if (process.platform !== "win32") {
168:       accessSync(filePath, constants.X_OK);
169:     }
170:     return true;
171:   } catch {
172:     return false;
173:   }
174: }
