176: /**
177:  * One manager per workspace root.
178:  *
179:  * This used to be a single process-wide singleton that only existed if some host
180:  * called `initializeLSPManager()` — and NO host ever did. The `LSP` tool was
181:  * registered and advertised to the agent, but its first act is
182:  * `getLSPManager()`, so every invocation returned "LSP is not initialized".
183:  * The capability was dead on arrival in every product surface.
184:  *
185:  * Keying by root also fixes the design problem behind the singleton: an agent
186:  * can work across several workspaces in one process (worktrees, sub-agents), and
187:  * a language server is rooted at exactly one directory.
188:  */
189: const managers = new Map<string, LSPServerManager>();
190: /**
191:  * Use order, as a monotonic counter rather than a clock.
192:  *
193:  * `Date.now()` has millisecond resolution, so several workspaces touched in the
194:  * same tick would tie and the LRU sort would pick an arbitrary victim — possibly
195:  * the one being actively used.
196:  */
197: const useOrder = new Map<string, number>();
198: let useTick = 0;
199: 
200: /**
201:  * Most workspaces to keep language servers alive for at once.
202:  *
203:  * Per-workspace managers removed the single-cwd bug, but replaced it with a map
204:  * that only ever grows: a long-lived Desktop session that touches many
205:  * worktrees would accumulate a language server per root. Evicting the
206:  * least-recently-used keeps the process bounded — an evicted workspace simply
207:  * pays a cold start the next time it is used.
208:  */
209: const MAX_LIVE_WORKSPACES = 4;
210: 
211: export function initializeLSPManager(cwd: string): LSPServerManager {
212:   useOrder.set(cwd, ++useTick);
213:   const existing = managers.get(cwd);
214:   if (existing) return existing;
215:   const created = new LSPServerManager(cwd);
216:   managers.set(cwd, created);
217:   evictLeastRecentlyUsed();
218:   return created;
219: }
220: 
221: /** Shut down the oldest workspaces once the live set exceeds its cap. */
222: function evictLeastRecentlyUsed(): void {
223:   if (managers.size <= MAX_LIVE_WORKSPACES) return;
224:   const ordered = [...managers.keys()].sort(
225:     (left, right) => (useOrder.get(left) ?? 0) - (useOrder.get(right) ?? 0),
226:   );
227:   for (const cwd of ordered.slice(0, managers.size - MAX_LIVE_WORKSPACES)) {
228:     const manager = managers.get(cwd);
229:     managers.delete(cwd);
230:     useOrder.delete(cwd);
231:     // Fire-and-forget: eviction must not make the caller wait on a shutdown
232:     // handshake with a server it is no longer using.
233:     void manager?.shutdownAll().catch(() => undefined);
234:   }
235: }
236: 
237: /**
238:  * Manager for `cwd`, creating it on first use.
239:  *
240:  * Lazy by design: spawning language servers eagerly at startup would cost every
241:  * session a process it may never use. Callers that only want to observe existing
242:  * state pass `{ create: false }`.
243:  */
244: export function getLSPManager(
245:   cwd?: string,
246:   options: { create?: boolean } = {},
247: ): LSPServerManager | undefined {
248:   if (cwd === undefined) {
249:     // Back-compat for callers with no workspace context: return the sole manager
250:     // when exactly one exists, otherwise nothing (ambiguous).
251:     return managers.size === 1 ? [...managers.values()][0] : undefined;
252:   }
253:   const existing = managers.get(cwd);
254:   if (existing) {
255:     // Refresh recency on READ too — a workspace being actively used must not be
256:     // the LRU victim just because it was created long ago.
257:     useOrder.set(cwd, ++useTick);
258:     return existing;
259:   }
260:   if (options.create === false) return undefined;
261:   return initializeLSPManager(cwd);
262: }
263: 
264: /** Shut down and forget one workspace's servers (session/workspace teardown). */
265: export async function shutdownLSPManager(cwd: string): Promise<void> {
266:   const manager = managers.get(cwd);
267:   if (!manager) return;
268:   managers.delete(cwd);
269:   useOrder.delete(cwd);
270:   await manager.shutdownAll();
271: }
272: 
273: /** Shut down every workspace's servers (process teardown). */
274: export async function shutdownAllLSPManagers(): Promise<void> {
275:   const all = [...managers.values()];
276:   managers.clear();
277:   useOrder.clear();
278:   await Promise.all(all.map((manager) => manager.shutdownAll()));
279: }
